args.content:
'use client'

import { useRouter } from 'next/navigation'
import { useEffect } from 'react'

export function ViewTransitions() {
  const router = useRouter()

  useEffect(() => {
    const navigationType = () =>
      typeof window !== 'undefined' && 'startViewTransition' in document

    if (!navigationType()) return

    const determineDirection = (targetPath: string): 'forward' | 'back' => {
      const currentDepth =
        window.location.pathname.split('/').filter(Boolean).length
      const targetDepth = targetPath.split('/').filter(Boolean).length
      return targetDepth >= currentDepth ? 'forward' : 'back'
    }

    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      const link = target.closest('a') as HTMLAnchorElement | null
      if (!link || !link.href) return

      const linkUrl = new URL(link.href, window.location.origin)
      if (linkUrl.origin !== window.location.origin) return
      if (link.target === '_blank') return
      if (e.metaKey || e.ctrlKey) return

      e.preventDefault()

      const direction = determineDirection(linkUrl.pathname)
      document.documentElement.setAttribute(
        'data-navigation-direction',
        direction,
      )

      const transition = document.startViewTransition(() => {
        router.push(linkUrl.pathname + linkUrl.search)
        return new Promise<void>((resolve) => {
          const done = () => {
            if (window.location.pathname === linkUrl.pathname) {
              resolve()
              return true
            }
            if (attempts > 100) {
              resolve()
              return true
            }
            return false
          }

          let attempts = 0
          const poll = () => {
            attempts++
            if (!done()) {
              requestAnimationFrame(poll)
            }
          }
          requestAnimationFrame(poll)
        })
      })

      transition.finished.then(() => {
        document.documentElement.removeAttribute('data-navigation-direction')
      })
    }

    document.addEventListener('click', handleClick, true)

    return () => {
      document.removeEventListener('click', handleClick, true)
    }
  }, [router])

  return null
}

